\begin{ex}%[7D6N2]
Tìm hai số ${x}$, ${y}$ biết $\dfrac{6}{x}= \dfrac{1}{y}$ và ${ x+y=21 }$
\choice
{ \True ${x=18}$ và ${y=3}$  }
   {  ${x=3}$ và ${y=18}$ }
     { ${x=-3}$ và ${y=-18}$  }
    { ${x=-18}$ và ${y=-3}$  }
\loigiai{
$\dfrac{6}{x}= \dfrac{1}{y} =\dfrac{7}{x+y}= \dfrac{7}{21} = \dfrac{1}{3}$\\
Suy ra ${x=18}$ và ${y=3}$.
}\end{ex}

\begin{ex}%[7D6N2]
Tìm hai số ${x}$, ${y}$ biết $\dfrac{4}{x}= \dfrac{-2}{y}$ và ${ x+y=-4 }$
\choice
{  ${x=4}$ và ${y=-8}$ }
   { \True ${x=-8}$ và ${y=4}$  }
     { ${x=-4}$ và ${y=8}$  }
    { ${x=8}$ và ${y=-4}$  }
\loigiai{
$\dfrac{4}{x}= \dfrac{-2}{y} =\dfrac{2}{x+y}= \dfrac{2}{-4} = - \dfrac{1}{2}$\\
Suy ra ${x=-8}$ và ${y=4}$.
}\end{ex}

