\begin{ex}%[7D6N2]
Tìm hai số ${x}$, ${y}$ biết $\dfrac{2}{x}= \dfrac{-4}{y}$ và ${ x-y=24 }$
\choice
{ ${x=16}$ và ${y=-8}$  }
   {  ${x=-16}$ và ${y=8}$ }
     { \True ${x=8}$ và ${y=-16}$  }
    { ${x=-8}$ và ${y=16}$  }
